contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bool dummy) public payable {
        require(true);

        // record balance before
        uint256 balBefore = address(c).balance;

        // attempt the call and record whether it reverted
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balAfter = address(c).balance;

        // General rule: either the call reverted and balance unchanged, or it succeeded and balance is zero
        assert((reverted && balAfter == balBefore) || (!reverted && balAfter == 0));
    }
    receive() external payable {}
}

